  settings_search_idx_fda: 'macOS отозвал у Xenon полный доступ к диску. Это происходит при каждом обновлении, потому что разрешение привязано к подписи приложения. Пока его нет, Xenon не индексирует домашнюю папку: иначе macOS запрашивал бы доступ к «Рабочему столу», «Документам», «Загрузкам», «Фото» и «Музыке» при каждом проходе. Включите снова: Системные настройки → Конфиденциальность и безопасность → Полный доступ к диску, уберите Xenon из списка и добавьте заново.',
  disk_fda_title: 'macOS отозвал разрешение у Xenon',
