  settings_search_idx_off_wds: 'Поиск по-прежнему находит файлы через собственный индекс Windows: он принадлежит Microsoft, а Xenon лишь обращается к нему.',
  settings_idle_anim_pause: 'Останавливать анимации при бездействии',
  settings_idle_anim_pause_hint: 'Через минуту без действий останавливает аврору, сетку и небольшие зацикленные анимации, чтобы снизить нагрузку на GPU; они возобновятся при следующем касании',
  settings_hybrid_gpu_pause: 'Меньше анимаций на гибридной графике',
  settings_hybrid_gpu_pause_hint: 'В этом ПК две видеокарты, и Xenon рисует на встроенной, у которой меньше запаса: аврора, сетка, анимированный фон и мелкие анимации неподвижны, графики меняются скачком, а поверх видео или GIF часы Ambient сплошные, а не стеклянные. Выключите, чтобы вернуть всё, ценой части кадров',
  settings_bg_code_frozen_gpu: 'На этом ПК фон останавливается через несколько секунд: в нём две видеокарты, и Xenon рисует на встроенной. Дело не в вашем коде. Это можно изменить пунктом «Меньше анимаций на гибридной графике» в разделе Внешний вид, Поверхность.',
