  streaming_setup_discord: 'Создайте приложение в Discord (Developer Portal), добавьте редирект http://localhost в OAuth2 и вставьте сюда Client ID и Client Secret. Настольное приложение Discord должно быть запущено.',
  streaming_discord_authorize: 'Откройте Discord и нажмите «Авторизовать» в появившемся окне.',
