  streaming_discord_busy: 'Локальное подключение Discord занято (возможно, его использует другое приложение). Подождите немного и снова нажмите «Подключить».',
  streaming_discord_pipedenied: 'Discord запущен от имени администратора, поэтому Xenon не может с ним связаться. Полностью закройте Discord (значок в трее → «Выход») и откройте его обычным способом, затем нажмите «Подключить». Ожидание не поможет.',
  streaming_discord_closed: 'Discord закрыл подключение. Проверьте, верен ли Client ID и вошло ли настольное приложение Discord под тем аккаунтом, который создал это приложение.',
  streaming_discord_denied: 'Авторизация в Discord отклонена. Подтвердите запрос: и убедитесь, что вы вошли под аккаунтом-владельцем приложения.',
  streaming_discord_timeout: 'Время окна авторизации истекло. Попробуйте снова и сразу нажмите «Авторизовать» в Discord.',
  streaming_token_failed: 'Вход не удался при обмене кода. Проверьте Client Secret и то, что URL перенаправления: ровно http://localhost.',
  streaming_discord_inflight: 'Один вход уже ждёт подтверждения: найдите всплывающее окно в Discord (или дождитесь, пока оно истечёт), прежде чем пробовать снова.',
  streaming_discord_badclientid: 'Discord отклонил Client ID. Скопируйте «Application ID» со страницы General Information вашего приложения в Developer Portal и введите его заново через «Изменить учётные данные».',
  streaming_discord_authfailed: 'Discord отказал в авторизации. Настольное приложение Discord должно быть выполнено под тем же аккаунтом, которому принадлежит это приложение в Developer Portal.',
  streaming_discord_invalidscope: 'Discord отклонил запрошенные разрешения. Нужный здесь доступ «rpc» выдаётся только аккаунту-ВЛАДЕЛЬЦУ приложения (или добавленному в тестеры OAuth2): проверьте, под каким аккаунтом выполнен вход в настольном приложении Discord. Discord также откажет, если ваше приложение: Activity (флаг «Embedded App»). Редирект к этой ошибке отношения не имеет.',
  streaming_discord_badsecret: 'Discord отклонил Client Secret. Откройте приложение в Developer Portal, сбросьте secret и вставьте новое значение через «Изменить учётные данные».',
  streaming_discord_network: 'Discord авторизовал вход, но этот ПК не смог связаться с discord.com, чтобы его завершить. Проверьте VPN, брандмауэр или прокси и снова нажмите «Подключить».',
  streaming_discord_id_shape: 'Это не похоже на Client ID от Discord: это длинное число с подписью «Application ID» на странице General Information вашего приложения (не Public Key и не Client Secret).',
