  ra_guide_sub: 'Шаги с 1 по 3 выводят панель на телефон дома. Остальное нужно, только если хотите пользоваться ею и вне дома.',
  ra_guide_group_home: 'Дома, по своей Wi-Fi',
  ra_guide_group_away: 'Вне дома (по желанию)',
  ra_guide_ack: 'Готово',
  ra_guide_undo: 'Ещё нет',
  ra_guide_s1: 'Включите доступ с других устройств',
  ra_guide_s1_body: 'Он выключен, пока вы сами его не включите. Пока он выключен, Xenon отвечает только этому ПК.',
  ra_guide_s2: 'Наведите телефон на QR-код',
  ra_guide_s2_body: 'Код. Это приглашение, а не пароль: он живёт три минуты и перестаёт работать после нескольких неверных попыток. Панель откроется в браузере телефона. На телефон ничего ставить не нужно.',
  ra_guide_s2_wait: 'Доступно, когда переключатель выше включён.',
  ra_guide_s3: 'Добавьте её на главный экран телефона',
  ra_guide_s3_body: 'На iPhone нажмите «Поделиться», затем «На экран «Домой»». На Android Chrome сам предложит установить. После этого Xenon открывается со своим значком на весь экран, и там работают микрофон и уведомления.',
  ra_guide_s4: 'Включите защищённый адрес',
  ra_guide_s4_body: 'Он даёт этому ПК собственное имя, которое работает откуда угодно, по зашифрованному соединению. Используется бесплатный Tailscale, а установку и вход Xenon берёт на себя. Учётную запись у Xenon вы не заводите.',
  ra_guide_s5: 'Включите HTTPS-сертификаты в своей учётной записи Tailscale',
  ra_guide_s5_body: 'Это единственный шаг, который Xenon не может сделать за вас. Откройте консоль Tailscale, пролистайте до HTTPS Certificates и нажмите Enable. Это бесплатно на любом тарифе. Потом вернитесь сюда: Xenon всё это время ждал.',
  ra_guide_s6: 'Установите Tailscale на телефон, та же учётная запись',
  ra_guide_s6_body: 'Скачайте из App Store или Google Play, войдите с той же учётной записью, что и только что, и включите его переключатель. Этот шаг забывают все. Без него телефон говорит, что вообще не может открыть адрес: ничего не сломалось, этот адрес существует только внутри вашей сети.',
  ra_guide_s7: 'Сопрягите телефон заново на новом адресе',
  ra_guide_s7_body: 'Нажмите «Добавить устройство» на шаге 2 и отсканируйте ещё раз. Браузер привязывает сопряжение к адресу, на котором оно сделано, поэтому телефон, сопряжённый по домашнему адресу, не сопряжён по защищённому. Дальше нужен только новый адрес: и дома, и в дороге.',
  ra_guide_done_title: 'Настройка закончена',
  ra_guide_done_body: 'Телефон сопряжён. Последнее: Xenon должен и дальше открываться на этом ПК?',
  ra_guide_keep: 'Оставить и здесь',
  ra_guide_hide: 'Скрыть Xenon на этом ПК',
  ra_guide_hide_note: 'Если скрыть, Xenon перестанет открываться на этом ПК, в том числе при входе в систему. В фоне он продолжает работать, так что телефон работает как прежде. Вернуть окно можно через значок Xenon рядом с часами или через «Настройки», затем «Экран».',
  ra_guide_hide_browser: 'Это панель внутри браузера, скрывать нечего. В приложении Xenon можно также выбрать, чтобы оно больше не открывалось на этом ПК.',
  settings_stack: 'Расположение плиток',
  settings_stack_auto: 'Авто',
  settings_stack_on: 'В одну колонку',
  settings_stack_off: 'Сеткой',
  settings_stack_note: 'Автоматически: подстраивается под экран, у вертикального экрана своя раскладка. В одну колонку складывает плитки стопкой, Сеткой сохраняет горизонтальную сетку.',
  settings_supporter_title: 'Код спонсора',
  settings_supporter_lead: 'Сохраните его здесь, и больше не придётся его вставлять: дропы для спонсоров открываются одним касанием. Он остаётся на этом ПК и никогда не отправляется на другие ваши экраны.',
  settings_supporter_save: 'Сохранить',
  settings_supporter_forget: 'Удалить',
